<script lang="ts">
  import { onMount } from 'svelte';
  import { ScanLine,Search,RefreshCw,Monitor,Smartphone,Play,Pause,Square,Settings2,Sun,Moon,ChevronDown,Box,ChevronRight,Copy,Download,FileJson,Eye,EyeOff,History,FileText,Code,Activity,Cpu,HardDrive,Check,AlertCircle,X,LoaderCircle,ArrowUpRight,Crosshair,Camera,FolderOpen } from '@lucide/svelte';
  import { Button } from '$lib/components/ui/button';
  import CapturePreview from './components/CapturePreview.svelte';
  import OriginalImage from './components/OriginalImage.svelte';
  import ModelManager from './components/ModelManager.svelte';
  import SettingsPanel from './components/SettingsPanel.svelte';
  import { api,native,Subscriptions } from './services/api';
  import type { WindowInfo,Settings,ModelEntry,ModelStatus,CaptureStatus,OcrStatus,Preview,Snapshot,Performance,AdbDevice,DownloadProgress } from './types';
  let settings=$state<Settings|null>(null),windows=$state<WindowInfo[]>([]),selected=$state<WindowInfo|null>(null),models=$state<ModelEntry[]>([]);
  let modelStatus=$state<ModelStatus>({status:'unloaded',id:null,device:null,loadMs:null,message:null});
  let captureStatus=$state<CaptureStatus>('idle'),ocrStatus=$state<OcrStatus>('idle'),performance=$state<Performance|null>(null);
  let liveFrame=$state<Preview|null>(null),snapshots=$state<Snapshot[]>([]),snapshotIndex=$state(0),followResults=$state(true),view=$state<'live'|'result'>('live');
  let originalImage=$state('');
  let search=$state(''),showAll=$state(false),showBoxes=$state(true),selectedBlock=$state<string|null>(null),resultTab=$state<'text'|'raw'|'history'>('text');
  let modelOpen=$state(false),settingsOpen=$state(false),busy=$state(''),refreshing=$state(false),error=$state(''),notice=$state(''),modelChoice=$state('Q8_0');
  let devices=$state<AdbDevice[]>([]),adbAddress=$state(''),progress=$state<DownloadProgress|null>(null),copyDone=$state(false);
  const current=$derived(snapshots[snapshotIndex]??null);
  const frame=$derived(view==='result'?current?.preview??null:liveFrame);
  const result=$derived(view==='result'?current?.result??null:null);
  const activeCapture=$derived(['running','paused','starting'].includes(captureStatus));
  const filtered=$derived(windows.filter(w=>`${w.title} ${w.processName} ${w.pid}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>{const recent=settings?.recentWindow;return Number(`${b.processName}|${b.title}`===recent)-Number(`${a.processName}|${a.title}`===recent);}));
  const captureLabels:Record<CaptureStatus,string>={idle:'未捕获',starting:'启动中',running:'捕获中',paused:'已暂停',stopping:'停止中',error:'捕获异常'};
  const modelLabels:Record<ModelStatus['status'],string>={unloaded:'未加载',loading:'加载中',ready:'已就绪',unloading:'卸载中',error:'加载异常'};
  const ocrLabels:Record<OcrStatus,string>={idle:'待命',waiting:'等待新帧',processing:'正在识别',error:'识别异常'};
  const ms=(value:number|null|undefined)=>value==null?'—':value>=1000?`${(value/1000).toFixed(2)} s`:`${Math.round(value)} ms`;
  function fail(e:unknown){error=e instanceof Error?e.message:String(e);}
  async function run(name:string,fn:()=>Promise<unknown>){busy=name;error='';try{await fn();}catch(e){fail(e);}finally{busy='';}}
  async function refreshWindows(){refreshing=true;try{windows=await api.windows(showAll);}finally{refreshing=false;}}
  async function refreshModels(){models=await api.models();modelStatus=await api.modelStatus();}
  async function saveSettings(next:Settings){await api.updateSettings(next);settings=await api.settings();}
  async function changeSettings(patch:Partial<Settings>){if(settings)await saveSettings({...settings,...patch});}
  async function selectWindow(w:WindowInfo){await run('select',async()=>{selected=await api.selectWindow(w.id);liveFrame=null;snapshots=[];snapshotIndex=0;view='live';settings=await api.settings();});}
  async function sourceChanged(value:'window'|'adb'){await run('source',async()=>{await api.stopCapture();liveFrame=null;snapshots=[];await changeSettings({captureSource:value});if(value==='adb')devices=await api.adbDevices();});}
  async function captureStart(){await run('capture',async()=>{view='live';liveFrame=null;snapshots=[];snapshotIndex=0;await api.startCapture();});}
  async function copyText(){if(!current)return;try{await navigator.clipboard.writeText(current.result.blocks.map(b=>b.text).filter(Boolean).join('\n\n'));copyDone=true;setTimeout(()=>copyDone=false,1800);}catch(e){fail(e);}}
  async function exportJson(){if(!current)return;const frameId=current.result.frameId;const path=await api.saveJson();if(path)await api.exportResult(frameId,path);}
  async function saveImage(){const path=await api.savePng();if(path)await api.saveScreenshot(path,view==='result');}
  function selectBlock(id:string){selectedBlock=id;resultTab='text';requestAnimationFrame(()=>document.getElementById(`result-${id}`)?.scrollIntoView({block:'nearest',behavior:'smooth'}));}
  $effect(()=>{document.documentElement.classList.toggle('light',settings?.theme==='light');document.documentElement.classList.toggle('dark',settings?.theme!=='light');});
  onMount(()=>{
    if(!native)return;
    const events=new Subscriptions();let disposed=false;
    async function init(){
      await Promise.all([
        events.add('capture-status',s=>{captureStatus=s;if(s==='idle'||s==='error'){liveFrame=null;snapshots=[];snapshotIndex=0;}}),events.add('capture-preview',p=>liveFrame=p),events.add('capture-error',fail),
        events.add('ocr-status',s=>ocrStatus=s),events.add('ocr-error',fail),events.add('model-status',s=>{modelStatus=s;if(s.id)modelChoice=s.id;}),events.add('performance-update',p=>performance=p),
        events.add('model-download-progress',p=>{progress=p;if(p.state==='complete')void refreshModels().catch(fail);}),
        events.add('ocr-result',s=>{const viewed=current?.result.frameId;snapshots=[s,...snapshots.filter(old=>old.result.frameId!==s.result.frameId)].slice(0,settings?.historyLimit??30);if(followResults){snapshotIndex=0;view='result';selectedBlock=null;}else{snapshotIndex=Math.max(0,snapshots.findIndex(item=>item.result.frameId===viewed));}}),
      ]);
      const [s,m,status,p,history]=await Promise.all([api.settings(),api.models(),api.status(),api.performance(),api.history()]);
      if(disposed)return;settings=s;models=m;captureStatus=status.capture;ocrStatus=status.ocr;selected=status.selected;performance=p;snapshots=history;if(status.warning)fail(status.warning);modelStatus=await api.modelStatus();if(modelStatus.id)modelChoice=modelStatus.id;await refreshWindows();
    }
    void init().catch(fail);return()=>{disposed=true;events.dispose();};
  });
</script>

<div class="app">
  <header class="topbar">
    <div class="brand"><div class="brand-mark"><ScanLine/></div><strong>Game<span>OCR</span></strong><span class="version">0.1</span></div>
    <div class="target-label"><span class="label">当前目标</span><span>{settings?.captureSource==='adb'?(settings.adbSerial||'选择 Android 设备'):(selected?.title||'选择一个窗口开始')}</span></div>
    <div class="top-actions row">
      {#if captureStatus==='paused'}<Button size="sm" onclick={()=>run('resume',api.resumeCapture)} disabled={!!busy}><Play/> 继续捕获</Button>
      {:else if captureStatus==='running'}<Button size="sm" variant="secondary" onclick={()=>run('pause',api.pauseCapture)} disabled={!!busy}><Pause/> 暂停</Button>
      {:else}<Button size="sm" onclick={captureStart} disabled={!native||!!busy||captureStatus==='starting'||(!selected&&settings?.captureSource!=='adb')}><Play/> 开始捕获</Button>{/if}
      <Button size="sm" variant="outline" disabled={!activeCapture||!!busy} onclick={()=>run('stop',api.stopCapture)}><Square/> 停止</Button>
      <div class="top-separator"></div>
      <button class="icon-btn" aria-label="切换主题" onclick={()=>run('theme',()=>changeSettings({theme:settings?.theme==='light'?'dark':'light'}))} disabled={!settings}>{#if settings?.theme==='light'}<Moon/>{:else}<Sun/>{/if}</button>
      <button class="icon-btn" aria-label="打开设置" onclick={()=>settingsOpen=true} disabled={!settings}><Settings2/></button>
    </div>
  </header>
  {#if !native}<div class="browser-warning"><AlertCircle/> 这是界面预览。窗口捕获和本地 OCR 需要在 GameOCR 桌面程序中运行。</div>{/if}
  {#if error}<div class="notification error"><AlertCircle/><div><strong>操作未完成</strong><pre>{error}</pre></div><button class="icon-btn" aria-label="关闭错误" onclick={()=>error=''}><X/></button></div>{/if}
  {#if notice}<div class="notification"><Check/><span>{notice}</span><button class="icon-btn" aria-label="关闭通知" onclick={()=>notice=''}><X/></button></div>{/if}
  <main>
    <aside class="sidebar">
      <div class="source-section"><div class="row spread"><span class="label">捕获来源</span><span class="chip">LOCAL</span></div><div class="segmented"><button class:active={settings?.captureSource!=='adb'} onclick={()=>sourceChanged('window')} disabled={!settings||!!busy}><Monitor/> Windows</button><button class:active={settings?.captureSource==='adb'} onclick={()=>sourceChanged('adb')} disabled={!settings||!!busy}><Smartphone/> Android</button></div></div>
      <div class="window-section">
        {#if settings?.captureSource==='adb'}
          <div class="row spread section-heading"><h2>已连接设备 <span>{devices.length}</span></h2><button class="icon-btn" aria-label="刷新 ADB" onclick={()=>run('adb',async()=>{devices=await api.adbDevices();})}><RefreshCw/></button></div>
          <div class="device-list">{#each devices as device}<button class="window-item" class:selected={settings.adbSerial===device.serial} disabled={activeCapture||device.status!=='device'} onclick={()=>run('device',()=>changeSettings({adbSerial:device.serial}))}><div class="window-icon"><Smartphone/></div><div class="window-info"><strong>{device.serial}</strong><small>{device.status} · {device.description}</small></div></button>{/each}{#if !devices.length}<div class="empty compact"><Smartphone/><p>未发现设备。连接模拟器的 ADB 地址，或在设置中指定 adb.exe。</p></div>{/if}</div>
          <div class="adb-connect"><input bind:value={adbAddress} placeholder="ADB 地址 · host:port" aria-label="ADB 连接地址"/><Button size="sm" variant="outline" disabled={!adbAddress||!!busy} onclick={()=>run('connect',async()=>{notice=await api.connectAdb(adbAddress);devices=await api.adbDevices();})}>连接设备</Button></div>
        {:else}
          <div class="row spread section-heading"><h2>窗口列表 <span>{filtered.length}</span></h2><button class="icon-btn" aria-label="刷新窗口" disabled={!native||refreshing} onclick={()=>refreshWindows().catch(fail)}><RefreshCw class={refreshing?'spinner':''}/></button></div>
          <div class="search-box"><Search/><input placeholder="搜索窗口、进程…" aria-label="搜索窗口或进程" bind:value={search}/></div>
          <label class="all-windows"><input type="checkbox" bind:checked={showAll} onchange={()=>refreshWindows().catch(fail)} disabled={!native}/> 显示全部窗口</label>
          <div class="window-list">
            {#each filtered as window (window.id)}
              <button class="window-item" class:selected={selected?.id===window.id} disabled={!window.capturable||!!busy} onclick={()=>selectWindow(window)} title={window.executablePath??window.title}>
                <div class="window-icon">{#if window.icon}<img src={window.icon} alt=""/>{:else}<Monitor/>{/if}</div>
                <div class="window-info"><strong>{window.title||'无标题窗口'}</strong><small>{window.processName} <span>· {window.minimized?'已最小化':`${window.width}×${window.height}`}</span></small></div>{#if selected?.id===window.id}<span class="selected-dot"></span>{/if}
              </button>
            {/each}
            {#if !filtered.length}<div class="empty compact"><Monitor/><strong>{search?'没有匹配的窗口':'等待选择窗口'}</strong><p>{native?'点击刷新，查看可捕获的应用和游戏。':'启动桌面应用后，可在此选择正在运行的窗口。'}</p></div>{/if}
          </div>
        {/if}
      </div>
      <div class="sidebar-bottom">
        <div class="row spread"><span class="label">推理模型</span><button class="text-button" onclick={()=>modelOpen=true} disabled={!native}>管理 <ArrowUpRight/></button></div>
        <select aria-label="选择模型" bind:value={modelChoice} disabled={!!busy||['loading','ready','unloading'].includes(modelStatus.status)}>{#each models as model}<option value={model.id}>{model.quantization}{model.installed?' · 已下载':' · 未下载'}</option>{/each}{#if !models.length}<option value="Q8_0">LightOnOCR-3 · Q8_0</option>{/if}</select>
        <div class="row model-summary"><span class="dot" class:on={modelStatus.status==='ready'}></span><span>{modelLabels[modelStatus.status]}</span><span class="mono">{modelStatus.device??'CPU / CUDA'}</span></div>
        {#if ['ready','error'].includes(modelStatus.status)}<Button variant="outline" size="sm" class="w-full" disabled={!!busy} onclick={()=>run('unload',api.unloadModel)}>卸载模型</Button>{:else}<Button variant="outline" size="sm" class="w-full" disabled={!native||!!busy||modelStatus.status==='loading'||!models.find(m=>m.id===modelChoice)?.installed} onclick={()=>run('load',()=>api.loadModel(modelChoice))}>{#if modelStatus.status==='loading'}<LoaderCircle class="spinner"/>{:else}<Cpu/>{/if} 加载模型</Button>{/if}
        {#if modelStatus.message}<p class="backend-message" title={modelStatus.message}>{modelStatus.message}</p>{/if}<div class="quick-settings"><div class="row spread"><span class="label">识别配置</span><button class="icon-btn" aria-label="更多识别设置" onclick={()=>settingsOpen=true} disabled={!settings}><Settings2/></button></div>
          <label class="row spread"><span>识别模式</span><select aria-label="识别模式" value={settings?.mode??'grounding'} disabled={!settings||ocrStatus==='processing'} onchange={e=>run('mode',()=>changeSettings({mode:e.currentTarget.value as 'plain'|'grounding'}))}><option value="grounding">Grounding</option><option value="plain">普通 OCR</option></select></label>
          <div class="row spread"><span>截图 / OCR 间隔</span><span class="mono">{settings?`${settings.captureFps} FPS / ${settings.ocrIntervalMs} ms`:'—'}</span></div>
          <label class="row spread"><span>画面变化检测</span><input type="checkbox" checked={settings?.changeDetection??true} disabled={!settings} onchange={e=>run('change',()=>changeSettings({changeDetection:e.currentTarget.checked}))}/></label>
        </div>
        <div class="privacy"><span class="dot on"></span> 本地运行 · 图像不上传</div>
      </div>
    </aside>
    <section class="center">
      <div class="pane-header"><div class="row"><ScanLine/><strong>画面预览</strong><span class="chip"><span class="dot" class:on={captureStatus==='running'}></span>{captureLabels[captureStatus]}</span></div><div class="row preview-tools"><div class="view-tabs"><button class:active={view==='live'} onclick={()=>view='live'}>实时</button><button class:active={view==='result'} onclick={()=>{view='result';snapshotIndex=0;followResults=true;}} disabled={!snapshots.length}>识别帧</button></div><button class="icon-btn" class:enabled={showBoxes} aria-label={showBoxes?'隐藏边界框':'显示边界框'} onclick={()=>showBoxes=!showBoxes}>{#if showBoxes}<Eye/>{:else}<EyeOff/>{/if}</button><button class="icon-btn" aria-label="查看原始截图" disabled={!frame||(view==='result'&&snapshotIndex!==0)} onclick={()=>run('original',async()=>{originalImage=await api.originalScreenshot(view==='result');})}><Camera/></button><button class="icon-btn" aria-label="保存原始 PNG 截图" disabled={!frame||(view==='result'&&snapshotIndex!==0)} onclick={()=>run('image',saveImage)}><Download/></button></div></div>
      <div class="preview-container"><CapturePreview {frame} {result} selected={selectedBlock} {showBoxes} onSelect={selectBlock}/></div>
      <div class="insights"><div class="insight-title row spread"><span class="label">PERFORMANCE / 实时性能</span><Activity/></div><div class="metric-grid"><div><span>捕获帧率</span><strong>{performance?performance.captureFps.toFixed(1):'—'}<small> FPS</small></strong></div><div><span>最近识别</span><strong>{ms(performance?.lastOcrMs)}</strong></div><div><span>平均耗时</span><strong>{ms(performance?.averageOcrMs)}</strong></div><div><span>识别速率</span><strong>{performance?.ocrPerMinute??'—'}<small> 次 / 分</small></strong></div></div><div class="detail-metrics"><span>预处理 <b>{ms(performance?.preprocessingMs)}</b></span><span>推理 <b>{ms(performance?.inferenceMs)}</b></span><span>模型加载 <b>{ms(performance?.modelLoadMs)}</b></span><span>显存 <b>{performance?.vramMb!=null?`${performance.vramMb} MB`:'不可用'}</b></span></div></div>
    </section>
    <aside class="results">
      <div class="pane-header"><div class="row"><FileText/><strong>识别结果</strong><span class="count">{current?.result.blocks.length??0}</span></div><div class="row"><button class="icon-btn" aria-label="复制全部文字" disabled={!current} onclick={copyText}>{#if copyDone}<Check/>{:else}<Copy/>{/if}</button><button class="icon-btn" aria-label="导出 JSON" disabled={!current} onclick={()=>run('export',exportJson)}><FileJson/></button></div></div>
      <div class="ocr-controls"><Button class="flex-1" size="sm" disabled={modelStatus.status!=='ready'||!['running','paused'].includes(captureStatus)||ocrStatus==='processing'||!!busy} onclick={()=>run('once',api.recognizeOnce)}><Crosshair/> 单次识别</Button>{#if ocrStatus==='waiting'||ocrStatus==='processing'}<Button variant="outline" size="sm" onclick={()=>run('ocr-stop',api.stopOcr)}><Square/> 停止 OCR</Button>{:else}<Button variant="outline" size="sm" disabled={modelStatus.status!=='ready'||captureStatus!=='running'||!!busy} onclick={()=>run('ocr-start',api.startOcr)}><Play/> 连续</Button>{/if}</div>
      <div class="result-tabs"><button class:active={resultTab==='text'} onclick={()=>resultTab='text'}><FileText/> 文字</button><button class:active={resultTab==='raw'} onclick={()=>resultTab='raw'}><Code/> 原始输出</button><button class:active={resultTab==='history'} onclick={()=>resultTab='history'}><History/> 历史 <span>{snapshots.length}</span></button></div>
      <div class="result-body">
        {#if resultTab==='history'}
          {#each snapshots as item,index}<button class="history-item" class:active={snapshotIndex===index} onclick={()=>{snapshotIndex=index;followResults=false;view='result';resultTab='text';selectedBlock=null;}}><div class="row spread"><strong>FRAME {item.result.frameId}</strong><span>{new Date(item.result.timestamp).toLocaleTimeString('zh-CN')}</span></div><p>{item.result.blocks.map(b=>b.text).join(' ').slice(0,75)||'未识别到文字'}</p><small>{item.result.blocks.length} 个区域 · {ms(item.result.metrics.totalMs)}</small></button>{/each}
          {#if !snapshots.length}<div class="empty"><History/><strong>暂无识别历史</strong><p>识别结果会保留最近 {settings?.historyLimit??30} 次。</p></div>{/if}
        {:else if !current}
          <div class="empty results-empty"><div class="result-empty-icon"><FileText/></div><strong>文字将在这里出现</strong><p>加载模型并开始捕获后，点击单次识别或开启连续 OCR。</p><button class="text-button" onclick={()=>modelOpen=true} disabled={!native}>打开模型管理 <ChevronRight/></button></div>
        {:else if resultTab==='raw'}<pre class="raw-output">{current.result.rawOutput||'（空输出）'}</pre>
        {:else}
          <div class="result-info row spread"><span class="mono">FRAME {current.result.frameId}</span><span>{ms(current.result.metrics.totalMs)} · {current.result.device}</span></div>
          {#if current.result.truncated}<div class="truncated">输出已达到 Token / 上下文上限，可在设置中调整。</div>{/if}
          {#if !followResults}<button class="return-live" onclick={()=>{followResults=true;snapshotIndex=0;view='result';}}>正在查看历史 · 返回最新结果 <ChevronRight/></button>{/if}
          {#each current.result.blocks as block,index}<button id={`result-${block.id}`} class="result-block" class:active={selectedBlock===block.id} onclick={()=>{view='result';selectedBlock=block.id;}}><div class="row spread"><span class="block-index">{String(index+1).padStart(2,'0')}</span><span class="block-label">{block.label??'text'}</span></div><p>{block.text||'（无文字区域）'}</p><div class="coordinates">{#if block.bbox}<Box/> [{block.bbox.map(v=>Math.round(v)).join(', ')}]{:else}无位置标记{/if}</div></button>{/each}
          {#if !current.result.blocks.length}<div class="empty"><strong>未识别到文字</strong><p>可查看原始输出，或更换窗口后重试。</p></div>{/if}
        {/if}
      </div>
      <div class="result-footer"><div class="row"><span class="dot" class:on={ocrStatus==='processing'||ocrStatus==='waiting'}></span><span>{ocrLabels[ocrStatus]}</span>{#if ocrStatus==='processing'}<LoaderCircle class="spinner"/>{/if}</div><span>LightOnOCR-3</span></div>
    </aside>
  </main>
  <footer class="statusbar"><div class="row"><span class="dot" class:on={native}></span><span>{native?'本地引擎':'界面预览'}</span><span class="status-divider">/</span><span>{modelStatus.device??'未选择后端'}</span></div><div class="row"><span>跳过 <b>{performance?.skippedFrames??'—'}</b></span><span>丢弃 <b>{performance?.droppedFrames??'—'}</b></span><span>队列 <b>{performance?.queue??'空闲'}</b></span><span class="status-divider">|</span><span>WINDOWS 11 · X64</span></div></footer>
</div>
{#if originalImage}<OriginalImage src={originalImage} onClose={()=>originalImage=''}/>{/if}
{#if modelOpen}<ModelManager {models} status={modelStatus} {progress} onClose={()=>modelOpen=false} onRefresh={refreshModels} onError={e=>{if(progress)progress={...progress,state:'failed'};fail(e);}}/>{/if}
{#if settingsOpen&&settings}<SettingsPanel {settings} onClose={()=>settingsOpen=false} onSave={saveSettings} onError={fail}/>{/if}

<style>
  .app{height:100vh;display:flex;flex-direction:column;background:var(--background);color:var(--foreground)}.topbar{height:68px;border-bottom:1px solid var(--border);display:flex;align-items:center;padding:0 22px;gap:24px;flex-shrink:0;background:var(--panel)}.brand{display:flex;align-items:center;gap:10px;width:226px;flex-shrink:0}.brand-mark{width:31px;height:31px;border:1px solid #376153;border-radius:8px;display:grid;place-items:center;color:var(--primary);background:#22534120}.brand-mark :global(svg){width:21px;height:21px}.brand strong{font-size:20px;letter-spacing:-.5px;font-weight:650}.brand strong span{color:var(--primary)}.version{color:var(--muted);font-size:9px;font-family:Consolas,monospace;margin-top:5px}.target-label{display:flex;flex-direction:column;gap:5px;min-width:0;flex:1}.target-label .label{font-size:9px}.target-label>span:last-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.top-actions{flex-shrink:0;gap:9px}.top-separator{height:24px;border-left:1px solid var(--border);margin:0 7px}main{display:grid;grid-template-columns:272px minmax(350px,1fr) 338px;min-height:0;flex:1}.sidebar,.results{background:var(--panel);min-height:0;display:flex;flex-direction:column}.sidebar{border-right:1px solid var(--border)}.source-section{padding:20px 18px 17px}.segmented{display:flex;padding:3px;background:var(--background);border:1px solid var(--border);border-radius:6px;margin-top:14px}.segmented button{display:flex;align-items:center;justify-content:center;gap:7px;flex:1;padding:8px 0;border:0;color:var(--muted);background:transparent;border-radius:4px;font-size:11px}.segmented button.active{color:var(--foreground);background:var(--secondary);box-shadow:0 1px 3px #0003}.segmented :global(svg){width:14px;height:14px}.window-section{border-top:1px solid var(--border);min-height:130px;display:flex;flex-direction:column;flex:1}.section-heading{padding:12px 14px 7px 18px}.section-heading h2{font-size:12px;font-weight:600;margin:0}.